/**
 * The types `save/cards/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CardSaveRow, CardPresetSlotRow, CardsSaveExtract
 * depends    —
 * used by    src/save/cards/index, src/save/cards/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from read.ts

export interface CardSaveRow {
  index: number
  slug: string | null
  name: string | null
  level: number
  count: number
  unlocked: boolean
  active: boolean
  masteryUnlocked: boolean
}

export interface CardPresetSlotRow {
  presetIndex: number
  slotIndex: number
  cardIndex: number | null
  card: CardSaveRow | null
}

export interface CardsSaveExtract {
  slotsUnlocked: number | null
  cardsBoughtTotal: number | null
  currentPreset: number | null
  presetNames: string[]
  cards: CardSaveRow[]
  equippedCards: CardSaveRow[]
  presetSlots: CardPresetSlotRow[]
  warnings: string[]
}
